def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find the solid 3-colored divider.
    green_rows = [r for r in range(h) if all(grid[r][c] == 3 for c in range(w))]
    green_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    horizontal = bool(green_rows)

    if horizontal:
        k = len(green_rows)
        n = (h + 1) // (k + 1)
    else:
        k = len(green_cols)
        n = (w + 1) // (k + 1)
    step = k + 1

    def origin(i, j):
        return (i * step, j * step)

    # Recover the repeated k-by-k pattern from any occupied tile.
    pattern = None
    for i in range(n):
        for j in range(n):
            r0, c0 = origin(i, j)
            tile = [[grid[r0 + r][c0 + c] for c in range(k)] for r in range(k)]
            if any(v in (2, 8) for row in tile for v in row):
                pattern = [[2 if v == 8 else v for v in row] for row in tile]
                break
        if pattern is not None:
            break

    if pattern is None:
        return out

    # Remove the divider, then place a copy of the pattern at each
    # position indicated by a 2 in the pattern itself.
    for r in green_rows:
        for c in range(w):
            out[r][c] = 0
    for c in green_cols:
        for r in range(h):
            out[r][c] = 0

    for i in range(n):
        for j in range(n):
            if pattern[i][j] != 2:
                continue
            r0, c0 = origin(i, j)
            for r in range(k):
                for c in range(k):
                    out[r0 + r][c0 + c] = pattern[r][c]
            out[r0 + i][c0 + j] = 8

    return out
